Once you scaffold it, add this to **`src/extension.ts`** (TypeScript) and it will monitor the clipboard by polling and detecting changes, and it will clean up on deactivate:

```ts
import * as vscode from 'vscode';

let clipboardInterval: NodeJS.Timeout | undefined;

export function activate(context: vscode.ExtensionContext) {
  let lastText = '';

  const poll = async () => {
    try {
      const text = await vscode.env.clipboard.readText();
      if (text !== lastText) {
        lastText = text;
        // TODO: react to clipboard change
        console.log('Clipboard changed:', text);
        // or vscode.window.showInformationMessage('Clipboard changed');
      }
    } catch (err) {
      console.error('Failed to read clipboard:', err);
    }
  };

  void poll();
  clipboardInterval = setInterval(poll, 500);

  context.subscriptions.push({
    dispose: () => {
      if (clipboardInterval) clearInterval(clipboardInterval);
      clipboardInterval = undefined;
    }
  });
}

export function deactivate() {
  if (clipboardInterval) clearInterval(clipboardInterval);
  clipboardInterval = undefined;
}
```

